import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"明爻第十","description":"杭氏易学 - 明爻第十","frontmatter":{"title":"明爻第十","description":"杭氏易学 - 明爻第十"},"headers":[],"relativePath":"zh/classics/hangshi/011.md","filePath":"zh/classics/hangshi/011.md"}'),l={name:"zh/classics/hangshi/011.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"明爻第十",tabindex:"-1"},[r("明爻第十 "),e("a",{class:"header-anchor",href:"#明爻第十","aria-label":"Permalink to “明爻第十”"},"​")],-1),e("p",null,"积爻而成卦，故爻为卦之体。爻动而卦变，故爻又为卦之用。卦之体用，具在于爻。《说卦传》曰：“昔者圣人之作《易》也，将以顺性命之理。是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。兼三才而两之，故《易》六画而成卦。分阴分阳，迭用柔刚，故《易》六位而成章。”《系传》曰：“《易》之为书也，广大悉备。有天道焉，有人道焉，有地道焉。兼三才而两之，故六。六者非它也，三才之道也。道有变动故曰爻，爻有等故曰物，物相杂故曰文。文不当故吉凶生焉。”又曰：“《易》之为书也不可远，为道也屡迁。变动不居，周流六虚。上下无常，刚柔相易。不可为典要，唯变所适。”又曰：“爻也者效此者也，象也者像此者也。爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。”孔子之所以言爻者，详且备矣。后世言《易》者，既昧于象数，而六虚六位之义，亦泛焉而莫知所指。每卦仅就所见之上下六爻，为承应当否，卦之情其何由见哉！",-1),e("p",null,"卦气由下生，故以下为初。重三画之卦为六画，仍分三才。阳奇阴偶，阳刚阴柔。以配天地，中爻为人，曰仁曰义。上下进退，为内外两象之中枢。孔子赞《易》，《彖传》以内外两象之阴阳刚柔，释一卦之义。《象传》则专取中爻，联合上下象数，以人合天。六十四卦《象传》，皆曰“君子以”或“先王以”者，即以人事明天地之道者也。天地之道往复不穷，而人事之千变万化，皆在三四两爻之反复。孔子曰“其初难知，其上易知，本末也”，《大过?彖》曰“本末弱也”。明六爻之本末，而后一卦之体用可知。而元亨利贞，亦可以阴阳之升降上下而明其序也。",-1),e("p",null,"端木氏曰：《易》太极含三为一，乾坤上下中，上天极，立在下地极，而中人极。离坎天地中，日月二人象，天地中人道，离坎交中，天地间生人。",-1),e("p",null,"天地颠，乾下首，生人出。乾是坎，北极艮背。坤是离，南极巽高。而中极人道，震兑出入，天地大义人之终始。此六爻三极之道也。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
